__NUXT_JSONP__("/inclusion/noticias/sistema_nacional_de_cuidados_requiere_no_solo_mas_recursos_sino_una_mejor_planeacion_especialistas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u){return {data:[{post:{slug:"sistema_nacional_de_cuidados_requiere_no_solo_mas_recursos_sino_una_mejor_planeacion_especialistas",title:"Sistema Nacional de Cuidados requiere no sólo más recursos, sino una mejor planeación, especialistas",date:"2026-01-08T15:40:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fc848a31d-2b92-4ca2-8262-e96106ad6787\u002F","img-alt":"Cuidados para la primera infancia",autor:"Ethos",link:"https:\u002F\u002Foem.com.mx\u002Fla-prensa\u002Fmetropoli\u002Fsistema-nacional-de-cuidados-requiere-no-solo-mas-recursos-sino-una-mejor-planeacion-especialistas-27556862",category:"inclusion",extracto:"Un cambio relevante es que el Presupuesto 2026 incorpora por primera vez recursos para el Sistema Nacional de Cuidados, pero son aún insuficientes.",toc:[{id:j,depth:k,text:l},{id:m,depth:k,text:n}],body:{type:"root",children:[{type:b,tag:d,props:{},children:[{type:a,value:"Un sistema de cuidados infantiles universal, gratuito y de calidad costaría a México el 1.16% del Producto Interno Bruto (PIB) anualmente, según el modelo presupuestal de ONU Mujeres y la Comisión Económica para América Latina y el Caribe (Cepal)."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A pesar del creciente interés por la conformación del Sistema Nacional de Cuidados (SNC), el presupuesto que acompaña a los programas que proveen cuidado y educación desde la federación ha decrecido, señala el Centro de Investigación Económica y Presupuestaria (CIEP), Erly Institute A.C. y Ethos Innovación en Políticas Públicas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En el documento “Cuidados para la primera infancia. Recomendaciones hacia la conformación del Sistema Nacional de Cuidados”, los investigadores señalan que la actual asignación presupuestaria se acerca apenas al 0.3% del PIB y prioriza servicios ligados a la seguridad social, lo que deja fuera al 40% de las"},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.oem.com.mx\u002Fla-prensa\u002Fmetropoli\u002Fsistema-nacional-de-cuidados-55-millones-de-personas-necesitan-atencion-26988636",rel:[f,g,h],target:i},children:[{type:a,value:" niñas"}]},{type:a,value:" y niños que no tienen acceso a este esquema."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Este enfoque, además de ser discriminatorio, restringe el alcance de los servicios de cuidado infantil y deja de atender a una parte importante de la población que más los necesita."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" Por ello, los investigadores recomiendan que es indispensable redistribuir el presupuesto, destinando una mayor proporción a los servicios de cuidado que beneficien a todas las niñas y niños, independientemente de su acceso a la seguridad social"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Además, advierten que, en términos reales, el presupuesto para cuidados (primera infancia, niñez y adolescencia) ha disminuido 1.1% en promedio anual en los últimos doce años (del 2013-2025), al pasar de 49.6 millones de pesos a 33.7 millones de pesos."}]},{type:a,value:c},{type:b,tag:o,props:{id:j},children:[{type:b,tag:e,props:{href:"#m%C3%A1s-recursos-y-m%C3%A1s-planeaci%C3%B3n",ariaHidden:p,tabIndex:q},children:[{type:b,tag:r,props:{className:[s,t]},children:[]}]},{type:a,value:l}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El Proyecto de Presupuesto de Egresos de la Federación (PPEF 2026) incorporó por primera vez un anexo transversal para cuidados, con el objetivo de visibilizar el conjunto de recursos destinados a programas relacionados a este ámbito, señala el CIEP."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"De acuerdo con el análisis “Sistema Nacional de"},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.oem.com.mx\u002Fla-prensa\u002Fmetropoli\u002Fazcapotzalco-entrega-700-apoyos-a-personas-con-discapacidad-27094691",rel:[f,g,h],target:i},children:[{type:a,value:" Cuidados."}]},{type:a,value:" Avances y limitaciones presupuestarias”, el Centro de Investigación Económica y Presupuestaria advierte que, a pesar de este cambio relevante, hay interrogantes respecto a los programas incluidos, el alcance de los recursos y la forma en que esto puede contribuir a la consolidación de un sistema integral de cuidados."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“El Anexo Transversal 31 del Proyecto de Presupuesto de Egresos de la Federación (PPEF) 2026 visibiliza por primera vez el gasto que podría contribuir a una sociedad del cuidado, con 466 mil 674.9 millones de pesos (mdp) (4.6 % del gasto neto total y 1.2 % del Producto Interno Bruto (PIB)”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Las erogaciones que plantea el anexo se configuran de programas existentes, sin recursos adicionales ni una nueva estrategia de política pública. Se identifica que los Programas Presupuestarios (PPs) con objetivos directamente vinculados al cuidado suman 38 mil 596 millones de pesos, 18.6 % menos que en 2025, debido a recortes y fusiones de programas clave”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“La reducción de recursos, falta de perspectiva de género e inclusión de objetivo de cuidado en los PPs muestran que una mayor visibilidad no necesariamente se traduce en una política integral para avanzar hacia un Sistema Nacional de Cuidados (SNC)”, indica el estudio."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" Además, señala que tres programas concentran más del 80 % del total: la Beca Universal para Educación Básica Rita Cetina (27.7 %), los Servicios de Atención a la Salud del IMSS (27.2 %) y la Pensión para el Bienestar de las Personas Adultas Mayores (26.4 %).   "}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"  A nivel institucional, la mayor parte del gasto se encuentra en la Secretaría de Bienestar (36.9 %), el IMSS (31.6 %) y la Secretaría de Educación Pública (29.2 %), que en conjunto concentran el 97.6 % de los recursos del anexo."}]},{type:a,value:c},{type:b,tag:o,props:{id:m},children:[{type:b,tag:e,props:{href:"#hacia-una-sociedad-de-cuidado",ariaHidden:p,tabIndex:q},children:[{type:b,tag:r,props:{className:[s,t]},children:[]}]},{type:a,value:n}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Al señalar que la incorporación del Anexo 31 en el Presupuesto de Egresos de la Federación 2026 no necesariamente implica recursos adicionales, sino una clasificación de recursos ya existentes, el documento del CIEP advierte que la ausencia de criterios claros para definir qué programas se incluyen en el anexo limita la posibilidad de evaluar la orientación del gasto."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por otra parte, la eliminación o fusión de programas que tenían objetivos cercanos a los cuidados genera un panorama que podría dificultar el seguimiento de estos recursos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Advierte que estas decisiones podrían afectar de manera significativa a poblaciones como "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.oem.com.mx\u002Fla-prensa\u002Fmetropoli\u002Faumenta-poblacion-en-situacion-de-calle-cuauhtemoc-concentra-mas-de-la-mitad-26398740",rel:[f,g,h],target:i},children:[{type:a,value:"mujeres"}]},{type:a,value:" cuidadoras, niñas, niños y adolescentes, personas adultas mayores y personas con discapacidad, cuya situación de vulnerabilidad podría agravarse al limitarse aún más su acceso a servicios públicos de cuidado."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Por ello, destacó la necesidad de asegurar que los PPs que contribuyen a la sociedad del cuidado incluyan perspectiva de género y atiendan de manera efectiva a la población que requiere y provee cuidado aún es materia pendiente."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El estudio agrega que la política de cuidados enfrenta el desafío de ir más allá de las transferencias monetarias y consolidar la infraestructura y los servicios públicos que permitan reducir, redistribuir y remunerar el trabajo de cuidados en todo el país. Para ello se requiere no solo mayor financiamiento, sino también una planeación que alinee el gasto con metas de igualdad y justicia social."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fsistema_nacional_de_cuidados_requiere_no_solo_mas_recursos_sino_una_mejor_planeacion_especialistas",extension:".md",createdAt:u,updatedAt:u}}],fetch:{},mutations:[]}}("text","element","\n","p","a","nofollow","noopener","noreferrer","_blank","más-recursos-y-más-planeación",3,"Más recursos y más planeación","hacia-una-sociedad-de-cuidado","Hacia una sociedad de cuidado","h3","true",-1,"span","icon","icon-link","2026-07-19T00:56:17.263Z")));